import { and, eq, isNull, like } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { newId } from "@/lib/id";
import { InvalidSlugError, uniqueSlug } from "@/lib/slug";
import { archivePatch } from "@/lib/soft-delete";
import { getDb, members, organizations, retiredOrgSlugs } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { toOrganization } from "./_mappers";
import type {
  CreateOrganizationInput,
  UpdateOrganizationInput,
} from "@/schemas/organization";
import type { OrgId, UserId } from "@/types/common";
import type { Organization } from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** A retired slug still resolves, and still blocks everyone else, until this instant. */
function holdIsActive(retiredAt: string, now: Date): boolean {
  const retiredMs = Date.parse(retiredAt);
  if (Number.isNaN(retiredMs)) return false;
  // Released at exactly ORG_SLUG_HOLD_DAYS after the rename, not a moment later.
  return now.getTime() < retiredMs + ORG_SLUG_HOLD_DAYS * MS_PER_DAY;
}

function isUniqueConstraintError(error: unknown): boolean {
  if (typeof error !== "object" || error === null) return false;
  const code = String((error as { code?: unknown }).code ?? "");
  if (code === "SQLITE_CONSTRAINT_UNIQUE") return true;
  const message = error instanceof Error ? error.message : "";
  return code === "SQLITE_CONSTRAINT" && message.includes("UNIQUE");
}

