export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();
  const row = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  // A slug this workspace retired still names it until the hold ends. The
  // row returned is the workspace as stored, so its current slug is the new one.
  const now = new Date();
  const held = db
    .select()
    .from(retiredOrgSlugs)
    .where(eq(retiredOrgSlugs.slug, slug))
    .all()
    .find((retirement) => holdIsActive(retirement.retiredAt, now));
  if (!held) return null;

  const org = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.id, held.orgId), isNull(organizations.archivedAt)))
    .get();
  return org ? toOrganization(org) : null;
}

