/**
 * Moves `orgId` onto `to` and retires the slug it holds now.
 *
 * `to` is refused when any other workspace — live or deleted — holds it as
 * its current slug, or holds it retired and still inside the hold. A slug
 * this same workspace retired is available to it immediately; taking it ends
 * that retirement. Renaming onto the current slug writes nothing.
 */
export async function renameOrgSlug(
  orgId: OrgId,
  to: string,
): Promise<Organization> {
  const db = getDb();
  try {
    return db.transaction((tx) => {
      const now = new Date();
      const current = tx
        .select()
        .from(organizations)
        .where(eq(organizations.id, orgId))
        .get();
      if (!current) throw new Error(`Organization ${orgId} not found`);
      if (current.slug === to) return toOrganization(current);

      const holder = tx
        .select({ id: organizations.id })
        .from(organizations)
        .where(eq(organizations.slug, to))
        .get();
      if (holder) throw new InvalidSlugError(to, "is not available");

      const retirements = tx
        .select()
        .from(retiredOrgSlugs)
        .where(eq(retiredOrgSlugs.slug, to))
        .all();
      const blocked = retirements.some(
        (row) => row.orgId !== orgId && holdIsActive(row.retiredAt, now),
      );
      if (blocked) throw new InvalidSlugError(to, "is not available");

      const stamp = toIsoTimestamp(now);
      const from = current.slug;

      tx.delete(retiredOrgSlugs)
        .where(and(eq(retiredOrgSlugs.orgId, orgId), eq(retiredOrgSlugs.slug, to)))
        .run();

      const row = tx
        .update(organizations)
        .set({ slug: to, updatedAt: stamp })
        .where(eq(organizations.id, orgId))
        .returning()
        .get();
      if (!row) throw new Error(`Organization ${orgId} not found`);

      const existing = tx
        .select({ id: retiredOrgSlugs.id })
        .from(retiredOrgSlugs)
        .where(
          and(eq(retiredOrgSlugs.orgId, orgId), eq(retiredOrgSlugs.slug, from)),
        )
        .get();
      if (existing) {
        tx.update(retiredOrgSlugs)
          .set({ retiredAt: stamp })
          .where(eq(retiredOrgSlugs.id, existing.id))
          .run();
      } else {
        tx.insert(retiredOrgSlugs)
          .values({ id: newId(), orgId, slug: from, retiredAt: stamp })
          .run();
      }

      return toOrganization(row);
    });
  } catch (error) {
    if (isUniqueConstraintError(error)) {
      throw new InvalidSlugError(to, "is not available");
    }
    throw error;
  }
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  const db = getDb();
  const rows = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();

  const now = new Date();
  const held = db
    .select({ slug: retiredOrgSlugs.slug, retiredAt: retiredOrgSlugs.retiredAt })
    .from(retiredOrgSlugs)
    .where(like(retiredOrgSlugs.slug, `${prefix}%`))
    .all()
    .filter((row) => holdIsActive(row.retiredAt, now))
    .map((row) => row.slug);

  return [...new Set([...rows.map((row) => row.slug), ...held])];
}

