/**
 * Changes the workspace URL. The slug is the one the caller typed: a collision
 * or a slug that fails the shared rules is refused, never suffixed. The
 * previous slug keeps resolving until its hold ends. Renaming to the slug the
 * workspace already has changes nothing and publishes nothing.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));
  assertValidSlug(input.slug);

  const current = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (current.slug === input.slug) return current;

  let updated: Organization;
  try {
    updated = await orgRepo.renameOrgSlug(input.orgId, input.slug);
  } catch (error) {
    if (error instanceof InvalidSlugError) throw error;
    throw error;
  }

  if (updated.slug === current.slug) return updated;

  await emit("organization.slug_changed", {
    ...envelope(current.id, actor.userId),
    from: current.slug,
    to: updated.slug,
  });

  await record(current.id, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `Slug ${current.slug} → ${updated.slug}`,
    metadata: { from: current.slug, to: updated.slug },
  });

  return updated;
}

