import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";
import { eq } from "drizzle-orm";
import { ORG_SLUG_HOLD_DAYS } from "@/config/constants";
import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, retiredOrgSlugs } from "@/server/db";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import { createOrganization, getOrganizationSummary, listOrganizationsForUser, renameOrganizationSlug, resolveOrgBySlug } from "@/server/services/organization-service";
import { resolveActorForOrg } from "@/server/services/session-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

const HOLD_MS = ORG_SLUG_HOLD_DAYS * 24 * 60 * 60 * 1000;
const offs: Unsubscribe[] = [];

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  while (offs.length > 0) offs.pop()?.();
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

function capture() {
  const seen: { from: string; to: string; actorId: string | null; orgId: string }[] = [];
  offs.push(
    subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function auditCount(orgId: Tenant["org"]["id"]) {
  const page = await activityRepo.listActivity({
    orgId,
    action: ["organization.slug_changed"],
    limit: 50,
    cursor: null,
  });
  return page;
}

describe("renameOrganizationSlug", () => {
  it("renames, keeps the old slug resolving, and publishes once", async () => {
    const tenant = await createTenant("slug-hold");
    const seen = capture();
    const before = tenant.org;

    const updated = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "slug-hold-next",
    });

    expect(updated.slug).toBe("slug-hold-next");
    expect(updated.name).toBe(before.name);
    expect(updated.plan).toBe(before.plan);
    expect(updated.ownerId).toBe(before.ownerId);
    expect(updated.logoUrl).toBe(before.logoUrl);
    expect(updated.settings).toEqual(before.settings);
    expect(updated.archivedAt).toBe(before.archivedAt);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: "slug-hold",
      to: "slug-hold-next",
    });

    const byNew = await resolveOrgBySlug("slug-hold-next");
    const byOld = await resolveOrgBySlug("slug-hold");
    expect(byNew?.id).toBe(tenant.org.id);
    expect(byNew?.slug).toBe("slug-hold-next");
    expect(byOld?.id).toBe(tenant.org.id);
    expect(byOld?.slug).toBe("slug-hold-next");

    const summary = await getOrganizationSummary(tenant.actors.owner, tenant.org.id);
    expect(summary.organization.slug).toBe("slug-hold-next");

    const listed = await listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === tenant.org.id)?.slug).toBe("slug-hold-next");

    const actor = await resolveActorForOrg(
      {
        userId: tenant.userIds.admin,
        email: "admin@slug-hold.test",
        activeOrgId: tenant.org.id,
        expiresAt: toIsoTimestamp(new Date(Date.now() + 60_000)),
      },
      "slug-hold",
    );
    expect(actor?.orgId).toBe(tenant.org.id);
    expect(actor?.role).toBe("admin");

    const page = await auditCount(tenant.org.id);
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "slug-hold", to: "slug-hold-next" },
    });
  });

  it("is a no-op when the slug does not change", async () => {
    const tenant = await createTenant("slug-noop");
    const seen = capture();
    const updated = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "slug-noop",
    });
    expect(updated.slug).toBe("slug-noop");
    expect(updated.updatedAt).toBe(tenant.org.updatedAt);
    expect(seen).toHaveLength(0);
    expect((await auditCount(tenant.org.id)).items).toHaveLength(0);
    expect(await orgRepo.findOrgBySlug("slug-noop")).toMatchObject({ id: tenant.org.id });
  });

  it("refuses a taken, reserved, or malformed slug without writing", async () => {
    const tenant = await createTenant("slug-refuse");
    const other = await createTenant("slug-taken");
    const seen = capture();

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "slug-taken",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "billing",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "Not A Slug",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    expect(seen).toHaveLength(0);
    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe("slug-refuse");
    expect((await orgRepo.findOrgById(other.org.id))?.slug).toBe("slug-taken");
  });

  it("needs the same permission as updating settings", async () => {
    const tenant = await createTenant("slug-perm");
    const other = await createTenant("slug-other-perm");
    const seen = capture();

    await expect(
      renameOrganizationSlug(tenant.actors.member, {
        orgId: tenant.org.id,
        slug: "slug-perm-next",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: tenant.org.id,
        slug: "slug-perm-next",
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect(seen).toHaveLength(0);
    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe("slug-perm");
  });

  it("keeps each earlier slug on its own hold and lets the workspace reclaim one", async () => {
    const tenant = await createTenant("slug-chain");
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "slug-chain-b",
    });
    const first = getDb()
      .select()
      .from(retiredOrgSlugs)
      .where(eq(retiredOrgSlugs.slug, "slug-chain"))
      .get();

    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "slug-chain-c",
    });

    const still = getDb()
      .select()
      .from(retiredOrgSlugs)
      .where(eq(retiredOrgSlugs.slug, "slug-chain"))
      .get();
    expect(still?.retiredAt).toBe(first?.retiredAt);

    expect((await resolveOrgBySlug("slug-chain"))?.slug).toBe("slug-chain-c");
    expect((await resolveOrgBySlug("slug-chain-b"))?.slug).toBe("slug-chain-c");

    const reclaimed = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "slug-chain",
    });
    expect(reclaimed.slug).toBe("slug-chain");
    expect(
      getDb()
        .select()
        .from(retiredOrgSlugs)
        .where(eq(retiredOrgSlugs.slug, "slug-chain"))
        .get(),
    ).toBeUndefined();
    expect((await resolveOrgBySlug("slug-chain-c"))?.slug).toBe("slug-chain");
    expect((await resolveOrgBySlug("slug-chain-b"))?.slug).toBe("slug-chain");
  });

  it("blocks other workspaces, including deleted ones, and suffixes creation", async () => {
    const live = await createTenant("slug-live");
    const deleted = await createTenant("slug-deleted");
    await orgRepo.archiveOrg(deleted.org.id);

    const mover = await createTenant("slug-mover");
    await expect(
      renameOrganizationSlug(mover.actors.admin, {
        orgId: mover.org.id,
        slug: "slug-deleted",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    await renameOrganizationSlug(live.actors.owner, {
      orgId: live.org.id,
      slug: "slug-live-now",
    });

    await expect(
      renameOrganizationSlug(mover.actors.admin, {
        orgId: mover.org.id,
        slug: "slug-live",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    expect((await orgRepo.findOrgById(mover.org.id))?.slug).toBe("slug-mover");

    const created = await createOrganization(mover.userIds.owner, {
      name: "Slug Live Copy",
      slug: "slug-live",
      plan: "free",
    });
    expect(created.slug).toBe("slug-live-2");
  });

  it("releases the slug at exactly the hold boundary", async () => {
    const start = new Date("2026-06-01T12:00:00.000Z");
    vi.useFakeTimers();
    vi.setSystemTime(start);

    const tenant = await createTenant("slug-expiry");
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "slug-expiry-now",
    });

    vi.setSystemTime(new Date(start.getTime() + HOLD_MS - 1));
    expect((await resolveOrgBySlug("slug-expiry"))?.id).toBe(tenant.org.id);

    const rival = await createTenant("slug-expiry-rival");
    await expect(
      renameOrganizationSlug(rival.actors.owner, {
        orgId: rival.org.id,
        slug: "slug-expiry",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    vi.setSystemTime(new Date(start.getTime() + HOLD_MS));
    expect(await resolveOrgBySlug("slug-expiry")).toBeNull();
    expect((await resolveOrgBySlug("slug-expiry-now"))?.slug).toBe("slug-expiry-now");

    const taken = await renameOrganizationSlug(rival.actors.owner, {
      orgId: rival.org.id,
      slug: "slug-expiry",
    });
    expect(taken.slug).toBe("slug-expiry");
    expect((await resolveOrgBySlug("slug-expiry"))?.id).toBe(rival.org.id);

    const derived = await createOrganization(rival.userIds.owner, {
      name: "Fresh",
      slug: "slug-expiry-now",
      plan: "free",
    });
    expect(derived.slug).not.toBe("slug-expiry-now");
  });
});

